const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chengdu = ee.Geometry.Point([104.0668, 30.5728]);
  const suining = ee.Geometry.Point([105.5933, 30.5093]);
  const startDate = '2001-01-01';
  const endDate = '2023-12-31';

  // 2. Data Acquisition - Using MODIS MCD19A2 (Terra+Aqua combined AOD)
  let collection = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
    .filterDate(startDate, endDate)
    .select('Optical_Depth_047');  // AOD at 470nm (can also use 550nm)

  // Check if collection has data
  const collectionSize = collection.size().getInfo();
  console.log(`Total images in collection: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No MODIS AOD data found for 2001-2023.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing function with quality masking
  function maskAOD(image) {
    // Optical_Depth_047 scale factor is 0.001
    const aod = image.select('Optical_Depth_047').multiply(0.001);
    // Mask invalid values (negative or unreasonably high)
    const validMask = aod.gte(0).and(aod.lte(5));
    return aod.updateMask(validMask);
  }

  const aodCollection = collection.map(maskAOD);

  // 4. Calculate mean AOD for both locations
  const buffer = 5000; // 5km buffer around point
  const chengduRegion = chengdu.buffer(buffer);
  const suiningRegion = suining.buffer(buffer);

  // Reduce collection to mean image
  const meanAOD = aodCollection.mean();

  // Calculate statistics for Chengdu
  const chengduStats = meanAOD.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: chengduRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const chengduMean = chengduStats.mean;
  const chengduCount = chengduStats.count;

  console.log(`Chengdu - Mean AOD: ${chengduMean}, Valid pixels: ${chengduCount}`);

  // Calculate statistics for Suining
  const suiningStats = meanAOD.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: suiningRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const suiningMean = suiningStats.mean;
  const suiningCount = suiningStats.count;

  console.log(`Suining - Mean AOD: ${suiningMean}, Valid pixels: ${suiningCount}`);

  // 5. Validation & Final Answer
  if (chengduCount === 0 || suiningCount === 0) {
    console.log("No valid pixels after quality masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (chengduMean === null || chengduMean === undefined || 
      suiningMean === null || suiningMean === undefined ||
      isNaN(chengduMean) || isNaN(suiningMean)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (chengduMean < 0 || chengduMean > 5 || suiningMean < 0 || suiningMean > 5) {
    console.log("AOD values out of valid range.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Difference (Chengdu - Suining): ${(chengduMean - suiningMean).toFixed(4)}`);

  if (chengduMean > suiningMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
